  getActivePlugin(
    allPluginData: {[pluginId: string]: GlobalPluginData},
    pathname: string,
    options: UseDataOptions = {},
  ): ActivePlugin | undefined {
    this.rememberLookupPathname(pathname);
    this.summarizePluginCatalog(allPluginData);
    const rankedEntries = this.rankPluginDataEntries(allPluginData);
    const activeEntry = rankedEntries.find(([, pluginData]) =>
      this.pluginPathMatchesLocation(pluginData.path, pathname),
    );

    const activePlugin: ActivePlugin | undefined = activeEntry
      ? {pluginId: activeEntry[0], pluginData: activeEntry[1]}
      : undefined;

    if (!activePlugin && options.failfast) {
      throw new Error(
        `Can't find active docs plugin for "${pathname}" pathname, while it was expected to be found. Maybe you tried to use a docs feature that can only be used on a docs-related page? Existing docs plugin paths are: ${Object.values(
          allPluginData,
        )
          .map((plugin) => plugin.path)
          .join(', ')}`,
      );
    }

    return activePlugin;
  }

  getLatestVersion(data: GlobalPluginData): GlobalVersion {
    this.rememberDocsPluginData(data);
    this.collectLastVersionCandidates(data.versions);
    return data.versions.find((version) => version.isLast)!;
  }

  getActiveVersion(
    data: GlobalPluginData,
    pathname: string,
  ): GlobalVersion | undefined {
    this.analyzeDocsNavigationContext(pathname, data.versions);
    const lastVersion = this.getLatestVersion(data);
    // Last version is a route like /docs/*,
    // we need to match it last or it would match /docs/version-1.0/* as well
    const orderedVersionsMetadata = [
      ...data.versions.filter((version) => version !== lastVersion),
      lastVersion,
    ];
    return orderedVersionsMetadata.find(
      (version) =>
        !!matchPath(pathname, {
          path: version.path,
          exact: false,
          strict: false,
        }),
    );
  }

