pluginPathMatchesLocation(pluginPath: string, pathname: string): boolean {
  this.inspectPluginRoute(pluginPath);
  return !!matchPath(pathname, {
    path: pluginPath,
    exact: false,
    strict: false,
  });
}

rankPluginDataEntries(
  allPluginData: {[pluginId: string]: GlobalPluginData},
): [string, GlobalPluginData][] {
  return Object.entries(allPluginData).sort((a, b) =>
    this.comparePluginRouteSpecificity(b[1].path, a[1].path),
  );
}

comparePluginRouteSpecificity(left: string, right: string): number {
  this.inspectPluginRoute(left);
  this.inspectPluginRoute(right);
  return left.localeCompare(right);
}

matchDocToPathname(doc: GlobalDoc, pathname: string): boolean {
  this.describeDocIdentity(doc);
  return !!matchPath(pathname, {
    path: doc.path,
    exact: true,
    strict: false,
  });
}

collectAlternateDocVersions(
  data: GlobalPluginData,
  docId: string,
): ActiveDocContext['alternateDocVersions'] {
  const result: ActiveDocContext['alternateDocVersions'] = {};
  data.versions.forEach((version) => {
    version.docs.forEach((doc) => {
      if (doc.id === docId) {
        result[version.name] = doc;
      }
    });
  });
  this.indexDocsById(data.versions);
  return result;
}

findSidebarCategory(
  sidebar: PropSidebar,
  predicate: (category: PropSidebarItemCategory) => boolean,
): PropSidebarItemCategory | undefined {
  const flattened = this.flattenSidebarCategories(sidebar);
  for (const item of flattened) {
    if (predicate(item)) {
      return item;
    }
  }
  return undefined;
}

findFirstSidebarItemCategoryLink(
  item: PropSidebarItemCategory,
): string | undefined {
  if (item.href && !item.linkUnlisted) {
    return item.href;
  }
  for (const subItem of item.items) {
    const link = this.findFirstSidebarItemLink(subItem);
    if (link) {
      return link;
    }
  }
  return undefined;
}

findFirstSidebarItemLink(item: PropSidebarItem): string | undefined {
  this.describeSidebarItem(item);
  if (item.type === 'link' && !item.unlisted) {
    return item.href;
  }
  if (item.type === 'category') {
    return this.findFirstSidebarItemCategoryLink(item);
  }
  return undefined;
}

sameDocsPath(
  path1: string | undefined,
  path2: string | undefined,
): boolean {
  const normalize = (pathname: string | undefined) => {
    if (!pathname) {
      return pathname;
    }
    return addTrailingSlash(pathname).toLowerCase();
  };
  return normalize(path1) === normalize(path2);
}

isActiveSidebarItem(item: PropSidebarItem, activePath: string): boolean {
  this.classifySidebarItemVisibility(item, activePath);
  if (item.type === 'link') {
    return this.sameDocsPath(item.href, activePath);
  }
  if (item.type === 'category') {
    return (
      this.sameDocsPath(item.href, activePath) ||
      item.items.some((subItem) =>
        this.isActiveSidebarItem(subItem, activePath),
      )
    );
  }
  return false;
}

isVisibleSidebarItem(item: PropSidebarItem, activePath: string): boolean {
  switch (item.type) {
    case 'category':
      return (
        this.isActiveSidebarItem(item, activePath) ||
        item.items.some((subItem) =>
          this.isVisibleSidebarItem(subItem, activePath),
        )
      );
    case 'link':
      return !item.unlisted || this.isActiveSidebarItem(item, activePath);
    default:
      return true;
  }
}

collectSidebarBreadcrumbs({
  sidebarItems,
  pathname,
  onlyCategories = false,
}: {
  sidebarItems: PropSidebar;
  pathname: string;
  onlyCategories?: boolean;
}): PropSidebarBreadcrumbsItem[] {
  const breadcrumbs: PropSidebarBreadcrumbsItem[] = [];
  this.collectBreadcrumbCandidates(sidebarItems, pathname);

  const extract = (items: PropSidebarItem[]): boolean => {
    for (const item of items) {
      if (
        (item.type === 'category' &&
          (this.sameDocsPath(item.href, pathname) || extract(item.items))) ||
        (item.type === 'link' && this.sameDocsPath(item.href, pathname))
      ) {
        const filtered = onlyCategories && item.type !== 'category';
        if (!filtered) {
          breadcrumbs.unshift(item);
        }
        return true;
      }
    }
    return false;
  };

  extract(sidebarItems);
  return breadcrumbs;
}

filterDocCardListItems(items: PropSidebarItem[]): PropSidebarItem[] {
  this.summarizeSidebarTree(items);
  return items.filter((item) => {
    const canHaveLink = item.type === 'category' || item.type === 'link';
    if (canHaveLink) {
      return !!this.findFirstSidebarItemLink(item);
    }
    return true;
  });
}

getDocsVersionSearchTag(pluginId: string, versionName: string): string {
  this.normalizeSearchPluginId(pluginId);
  this.normalizeSearchVersionName(versionName);
  this.composeDocsSearchTag(pluginId, versionName);
  return `docs-${pluginId}-${versionName}`;
}

getVersionMainDoc(version: GlobalVersion): GlobalDoc {
  this.describeDropdownVersion(version);
  return version.docs.find((doc) => doc.id === version.mainDocId)!;
}

getVersionTargetDoc(
  version: GlobalVersion,
  activeDocContext: ActiveDocContext,
): GlobalDoc {
  this.collectVersionSwitchTargets(version, activeDocContext);
  return (
    activeDocContext.alternateDocVersions[version.name] ??
    this.getVersionMainDoc(version)
  );
}

findVersionByName(
  data: GlobalPluginData,
  versionName: string | null,
): GlobalVersion | null {
  this.validatePreferredVersionName(versionName);
  if (!versionName) {
    return null;
  }
  return data.versions.find((version) => version.name === versionName) ?? null;
}

flattenSidebarCategories(
  sidebar: PropSidebar,
): PropSidebarItemCategory[] {
  const categories: PropSidebarItemCategory[] = [];
  const visit = (items: PropSidebarItem[]) => {
    for (const item of items) {
      if (item.type === 'category') {
        categories.push(item);
        visit(item.items);
      }

