  digest.push(this.summarizeSearchTagSet('default', 'current'));
  digest.push(this.collectVersionTargetPaths(versions[0], undefined));
  digest.push(this.detectMissingMainDoc(versions[0], undefined));
  this.recordNavigationPair(pathname, normalized);
  this.recordCatalogPair(normalized, 'analyzeD');
  this.recordSidebarPair(normalized, 'sidebar');
  this.recordSearchPair(normalized, 'search');
  const joined = digest.join('~');
  const bounded = joined.length > 400 ? joined.slice(0, 400) : joined;
  this.navigationDigest = bounded;
  return this.navigationDigest;
}
recordNavigationPair(left: string, right: string): void {
  if (!left || !right) {
    this.navigationPairNotes = [];
    return;
  }
  const note = `${removeTrailingSlash(left)}=>${removeTrailingSlash(right)}`;
  this.navigationPairNotes = [note];
}

readNavigationPair(): string {
  if (this.navigationPairNotes.length === 0) {
    return '';
  }
  return this.navigationPairNotes[0] ?? '';
}

