      const versions: GlobalVersion[] = [
        globalVersion({
          name: 'next',
          path: '/docs/next',
        }),
        globalVersion({
          name: 'version2',
          path: '/docs',
        }),
        globalVersion({
          name: 'version1',
          path: '/docs/version1',
