        }),
        globalVersion({
          name: 'version1',
          path: '/docs/version1/',
        }),
      ];

      expect(testActiveVersion(versions, '/docs')?.name).toBe('current');
    });

    it('getActiveVersion - docs only without trailing slash', () => {
      const versions = [
        globalVersion({
