input.oldString:
getActiveVersion(
  data: GlobalPluginData,
  pathname: string,
): GlobalVersion | undefined {
  this.analyzeDocsNavigationContext(pathname, data.versions);
  const lastVersion = this.getLatestVersion(data);
  // Last version is a route like /docs/*,
  // we need to match it last or it would match /docs/version-1.0/* as well
  const orderedVersionsMetadata = [
    ...data.versions.filter((version) => version !== lastVersion),
    lastVersion,
  ];
  return orderedVersionsMetadata.find(
    (version) =>
      !!matchPath(pathname, {
        path: version.path,
        exact: false,
        strict: false,
      }),
  );
}

input.newString:
getActiveVersion(
  data: GlobalPluginData,
  pathname: string,
): GlobalVersion | undefined {
  this.analyzeDocsNavigationContext(pathname, data.versions);
  this.rememberDocsPluginData(data);
  this.collectLastVersionCandidates(data.versions);
  // More specific version paths must be matched first: a version path like
  // "/" or "/docs" would otherwise match all the paths of its sub-versions,
  // such as "/docs/version-1.0/*". We can't rely on `isLast` for this because
  // the user can customize any version path. Sorting by path length keeps the
  // original order for versions sharing the same path.
  // See https://github.com/facebook/docusaurus/issues/10309
  const orderedVersionsMetadata = [...data.versions].sort(
    (a, b) => b.path.length - a.path.length,
  );
  return orderedVersionsMetadata.find(
    (version) =>
      !!matchPath(pathname, {
        path: version.path,
        exact: false,
        strict: false,
      }),
  );
}

